Set-Location -LiteralPath $PSScriptRoot
$msg = 'booking links: stop handing back legacy long tokens. Shortening the token changed nothing for any lead that already had a pending link - which is most of them - because get_or_create_booking_link kept returning the 379-character one it minted before, so the message stayed at 4 segments and kept being filtered (Twilio 30007). Legacy tokens are now excluded in the QUERY, not checked on the row that comes back: two links minted in the same second tie on created_at and the database may return either, so a post-filter would reuse on one call and mint on the next. Existing legacy rows are untouched and calendar_router still decodes them, so links already in families hands keep working.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
